import { resolveRecipe, recipeCapabilityRequirements, recipeCapabilityDiagnostics } from '@cossackframework/scaffold/registry';

const recipe = resolveRecipe({ adapter: 'cloudflare', preset: 'minimal', features: ['protected-route'] });
if (!recipe.resolvedFeatures.includes('protected-route')) throw new Error('Feature was not selected');
const requirements = recipeCapabilityRequirements(recipe);
if (!requirements.some(use => use.feature === 'protected-route' && use.requires.transports?.includes('http'))) {
  throw new Error('HTTP recipe requirement is missing');
}
if (recipeCapabilityDiagnostics(recipe).length) throw new Error('Unexpected host capability failure');
for (const feature of ['auth', 'database', 'ui'] as const) {
  if (!recipe.resolvedFeatures.includes(feature)) throw new Error('Dependency was not selected');
}
if (!requirements.some(use => use.requires.cloudflareBindings?.includes('DB'))) throw new Error('D1 binding requirement is missing');
let rejected = false;
try { resolveRecipe({ adapter: 'node', database: 'd1', features: ['protected-route'] }); } catch { rejected = true; }
if (!rejected) throw new Error('Unsupported database selection was accepted');

import { resolveRecipe, resolveFeatures, recipeCapabilityRequirements, recipeCapabilityDiagnostics,
  PRESET_REGISTRY, DATABASE_PROVIDERS, AUTH_METHODS, OAUTH_PROVIDERS, UI_THEMES, DASHBOARD_MODULES } from '@cossackframework/scaffold/registry';
const recipe = resolveRecipe({adapter: 'cloudflare', preset: 'full-stack', database: 'd1',
  features: ['schedules', 'notifications', 'workflows'], authMethods: ['credentials', 'oauth'], oauth: ['github'], theme: 'blue', dashboardModules: ['users', 'sessions']});
if (!DATABASE_PROVIDERS[recipe.config.database].adapters.includes(recipe.adapter)) throw Error('Unsupported provider');
if (!resolveFeatures(['schedules', 'notifications']).includes('jobs')) throw Error('Missing jobs dependency');
if (!PRESET_REGISTRY['full-stack'] || !AUTH_METHODS.includes('oauth') || !OAUTH_PROVIDERS.includes('github') || !UI_THEMES.includes('blue') || !DASHBOARD_MODULES.includes('sessions')) throw Error('Missing configuration');
const requirements = recipeCapabilityRequirements(recipe);
if (!requirements.length || recipeCapabilityDiagnostics(recipe).length) throw Error('Invalid coherent recipe');

import { readManifest, resolveManifestRecipe, detectProjectRuntime, planChanges, dependencyBaseline, planDependencyChanges } from '@cossackframework/scaffold';
export async function previewExisting(projectDir: string) {
  const manifest: unknown = await readManifest(projectDir);
  if (!manifest) throw Error('Existing manifest is required');
  const recipe = resolveManifestRecipe(manifest);
  const runtime = await detectProjectRuntime(projectDir, manifest);
  if (runtime !== recipe.adapter) throw Error('Runtime metadata mismatch');
  return planChanges(projectDir, recipe, manifest);
}
const previous = dependencyBaseline({dependencies: {'example-package': '1.0.0'}});
const result = planDependencyChanges({dependencies: {'example-package': '2.0.0'}}, {dependencies: {'example-package': '3.0.0'}}, previous);
if (result.next.dependencies?.['example-package'] !== '2.0.0' || !result.preserved.length) throw Error('User package edits must be preserved');
